let storageOK=true;
function readStore(key, fallback){try{const value=localStorage.getItem(key);return value?JSON.parse(value):fallback;}catch{storageOK=false;return fallback;}}
let records=readStore('missao-leitura-results-v1',[]);
if(!Array.isArray(records))records=[];
records=records.filter(r=>r&&typeof r.name==='string'&&typeof r.classroom==='string'&&Array.isArray(r.answers)&&Number.isFinite(r.elapsed)&&Number.isFinite(r.correct)&&Number.isFinite(r.pace));
const savedWords=readStore('missao-leitura-words-v1',[]);
BANKS.custom.words=Array.isArray(savedWords)?savedWords.filter(w=>typeof w==='string'):[];
function saveStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageOK=false;return false;}}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const norm = s => String(s).trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const personKey = r => norm(r.name)+'|'+norm(r.classroom);
const timeText = seconds => {const n=Math.max(0,Math.ceil(seconds));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;};
const preciseTime = seconds => seconds<60 ? `${seconds.toFixed(1).replace('.',',')} s` : `${Math.floor(seconds/60)} min ${(seconds%60).toFixed(1).replace('.',',')} s`;
const durationLabel = seconds => seconds < 60 ? `${seconds} s` : `${numberText(seconds/60)} min`;
const numberText = value => value.toLocaleString('pt-BR',{maximumFractionDigits:1});
let game=null, clockInterval=null, toastTimeout=null;
