function duration(){return (Number($('minutes').value)||0)*60+(Number($('seconds').value)||0);}
function setTime(seconds){$('minutes').value=Math.floor(seconds/60);$('seconds').value=seconds%60;updateSetup();}
function updateSetup(){if(game&&game.status!=='finished')return;const count=BANKS[$('level').value].words.length;const target=Math.min(Math.max(1,Math.floor(Number($('target').value)||1)),$('repeat').checked?500:count);$('listInfo').textContent=count?`${count} palavras disponíveis nesta lista.`:'Adicione palavras na aba Banco de palavras.';$('target').max=$('repeat').checked?500:Math.max(1,count);$('clock').textContent=timeText(duration());$('progressLabel').textContent=`0 de ${target} ${$('readingMode').value==='frases'?'frases':'palavras'}`;$('goalValue').textContent=`${target} ${$('readingMode').value==='frases'?'frases':''} em ${durationLabel(duration())}`;document.querySelectorAll('[data-time]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.time)===duration()));}
$('level').addEventListener('change',()=>{const count=BANKS[$('level').value].words.length;if(!$('repeat').checked&&count&&Number($('target').value)>count)$('target').value=count;updateSetup();});
['minutes','seconds','target','level'].forEach(id=>$(id).addEventListener('input',updateSetup));
document.querySelectorAll('[data-time]').forEach(b=>b.addEventListener('click',()=>setTime(Number(b.dataset.time))));
function shuffled(words){const a=[...words];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function elapsed(){if(!game)return 0;return Math.min(game.limit,game.used+(game.status==='running'?(performance.now()-game.started)/1000:0));}
function lockSetup(locked){[...$('setupForm').elements].forEach(el=>{if(el.id!=='sound')el.disabled=locked;});$('largeTime').disabled=locked;}
