$('keypad').addEventListener('click',event=>{const b=event.target.closest('[data-digit]');if(!b)return;timeDigits=(timeDigits==='0000'?'':timeDigits.replace(/^0+/,''))+b.dataset.digit;timeDigits=timeDigits.slice(-4);renderKeypad();});
$('clearTime').addEventListener('click',()=>{timeDigits='0000';renderKeypad();});$('backspaceTime').addEventListener('click',()=>{timeDigits=timeDigits.slice(0,-1);renderKeypad();});$('applyTime').addEventListener('click',()=>{const p=timeDigits.padStart(4,'0');const m=Number(p.slice(0,2)),s=Number(p.slice(2));if(s>59||m*60+s<1||m*60+s>3600){$('keypadError').textContent='Use de 00:01 a 60:00, com segundos de 00 a 59.';return;}setTime(m*60+s);$('timerDialog').close();$('keypadError').textContent='';});$('closeTimer').addEventListener('click',()=>$('timerDialog').close());
