function roundWords(words,target,random,repeat){let result=[];do{let part=random?shuffled(words):[...words];if(random&&part.length>1&&result.at(-1)===part[0]){const other=part.findIndex(w=>w!==part[0]);if(other>0)[part[0],part[other]]=[part[other],part[0]];}result.push(...part);}while(repeat&&result.length<target);return result.slice(0,target);}
function beginReading(){if(!game||game.status==='finished')return;game.status='running';game.started=performance.now();game.used=0;$('stateTag').textContent='MISSÃO EM ANDAMENTO';$('stateTag').classList.add('running');$('wordPrompt').textContent='Leia em voz alta';$('word').textContent=game.words[0];colorWord();displayReading();$('encouragement').textContent=game.mode==='frases'?'Leia a frase, linha por linha.':'Você consegue. Uma palavra de cada vez.';$('correct').disabled=false;$('skip').disabled=false;$('pause').disabled=false;$('finish').textContent='Encerrar rodada';$('jogar').classList.add('running');playSound('go');}
function cancelPreparation(){clearInterval(clockInterval);game.status='finished';lockSetup(false);$('finish').disabled=true;$('finish').textContent='Encerrar rodada';resetReady();}
let audioContext;
function initAudio(){if(!$('sound').checked)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume().catch(()=>{});}catch{}}
function playSound(type){if(!$('sound').checked||!audioContext)return;try{const tones=type==='win'?[523,659,784,1047,1319]:type==='end'?[659,523,392]:type==='go'?[784]:[440];tones.forEach((frequency,i)=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.value=frequency;const start=audioContext.currentTime+i*.15;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.13,start+.015);gain.gain.exponentialRampToValueAtTime(.001,start+.5);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(start);oscillator.stop(start+.55);});}catch{}}
function fireworks(){const el=$('celebration');el.hidden=false;el.innerHTML=Array.from({length:42},(_,i)=>`<span style="--dx:${Math.round((Math.random()-.5)*1000)}px;--dy:${Math.round((Math.random()-.5)*700)}px;--delay:${i%7*.04}s;color:${['#ffbd35','#ff6d87','#7657d4','#36b9a2','#50a5e9'][i%5]}">${i%3?'✦':'★'}</span>`).join('');setTimeout(()=>{el.hidden=true;el.innerHTML='';},2400);}
const defaultThresholds=[10,25,30,40,50,60,70,80,90,100];
let rewardSettings=readStore('missao-leitura-rewards-v1',{thresholds:defaultThresholds,prize:'Prêmio combinado com a professora'});
if(!rewardSettings||!Array.isArray(rewardSettings.thresholds)||rewardSettings.thresholds.length!==10)rewardSettings={thresholds:defaultThresholds,prize:'Prêmio combinado com a professora'};
let rewardClaims=readStore('missao-leitura-claims-v1',{});if(!rewardClaims||typeof rewardClaims!=='object'||Array.isArray(rewardClaims))rewardClaims={};
function isoDay(date){return new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(date));}
function weekStart(day){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()-((d.getDay()+6)%7));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function weekCorrect(r,before=false){const key=personKey(r),week=weekStart(isoDay(r.date));return records.filter(p=>personKey(p)===key&&weekStart(isoDay(p.date))===week&&(!before||p.id!==r.id&&p.date<r.date)).reduce((sum,p)=>sum+p.correct,0);}
const starsAt=correct=>rewardSettings.thresholds.filter(goal=>correct>=goal).length;
function legacyStarsEarned(r){const before=weekCorrect(r,true);return starsAt(before+r.correct)-starsAt(before);}
// Replaced by persistent reward-cycle starMessage.
function renderMilestones(){$('milestoneList').innerHTML=rewardSettings.thresholds.map((n,i)=>`<div><span>${i+1}ª ★</span><strong>${n} palavras</strong></div>`).join('');}
// Replaced by persistent reward-cycle renderStars.
$('rewardName').value=rewardSettings.prize;$('starThresholds').value=rewardSettings.thresholds.join(', ');$('weekDate').value=isoDay(new Date());$('weekDate').addEventListener('change',renderStars);
$('saveRewards').addEventListener('click',()=>{const goals=$('starThresholds').value.split(/[,;\s]+/).filter(Boolean).map(Number);if(goals.length!==10||goals.some((n,i)=>!Number.isInteger(n)||n<1||n>100000||(i>0&&n<=goals[i-1]))){$('rewardNotice').textContent='Informe 10 números inteiros positivos em ordem crescente, separados por vírgulas.';return;}rewardSettings={thresholds:goals,prize:$('rewardName').value.trim()||'Prêmio combinado com a professora'};const saved=saveStore('missao-leitura-rewards-v1',rewardSettings);$('rewardNotice').textContent=saved?'Metas salvas. O mural foi atualizado.':'Metas alteradas nesta sessão; armazenamento indisponível.';renderStars();});
// Reward actions are handled by the cycle ledger.
document.querySelectorAll('[data-count]').forEach(button=>button.addEventListener('click',()=>{const count=Number(button.dataset.count);if(count>BANKS[$('level').value].words.length)$('repeat').checked=true;$('target').value=count;updateSetup();}));
$('repeat').addEventListener('change',()=>{if(!$('repeat').checked)$('target').value=Math.min(Number($('target').value),Math.max(1,BANKS[$('level').value].words.length));updateSetup();});
$('wordFullscreen').addEventListener('click',async()=>{if(document.fullscreenElement){await document.exitFullscreen();document.body.classList.remove('projection');}else{document.body.classList.add('projection');try{await document.documentElement.requestFullscreen();}catch{toast('Leitura ampliada. Use F11 para preencher a tela.');}}$('projector').textContent=document.body.classList.contains('projection')?'↙ Sair da projeção':'↗ Modo projeção';});

