function avatarFor(r){return animalSvg(animalProfiles[personKey(r)]??r.avatar??0);}
function rememberAvatar(name,classroom){animalProfiles[personKey({name,classroom})]=selectedAvatar;saveStore('missao-leitura-avatars-v1',animalProfiles);$('roundAvatar').innerHTML=animalSvg(selectedAvatar);}
function refreshStudentAvatar(){selectedAvatar=validAvatar(animalProfiles[personKey({name:$('student').value,classroom:$('classroom').value})]??0);$('avatarButtonFace').innerHTML=animalSvg(selectedAvatar);}
function renderAvatarPicker(){const animal=Math.floor(pendingAvatar/20),color=pendingAvatar%20;$('animalGrid').innerHTML=animalKinds.map(([name],i)=>`<button type="button" class="animal-choice ${i===animal?'chosen':''}" data-animal="${i}" aria-label="${name}" aria-pressed="${i===animal}">${animalSvg(i*20+color)}<span>${name}</span></button>`).join('');$('avatarColorGrid').innerHTML=avatarColors.map(([name,hex],i)=>`<button type="button" aria-label="Fundo ${name}" aria-pressed="${i===color}" class="avatar-swatch ${i===color?'chosen':''}" data-avatar-color="${i}" style="background:${hex}"></button>`).join('');$('avatarPreview').innerHTML=animalSvg(pendingAvatar);$('avatarDescription').textContent=animalKinds[animal][0]+' · fundo '+avatarColors[color][0];}
$('chooseAvatar').addEventListener('click',()=>{pendingAvatar=selectedAvatar;renderAvatarPicker();$('avatarDialog').showModal();});$('closeAvatar').addEventListener('click',()=>$('avatarDialog').close());
$('animalGrid').addEventListener('click',event=>{const b=event.target.closest('[data-animal]');if(!b)return;pendingAvatar=Number(b.dataset.animal)*20+pendingAvatar%20;renderAvatarPicker();});
$('avatarColorGrid').addEventListener('click',event=>{const b=event.target.closest('[data-avatar-color]');if(!b)return;pendingAvatar=Math.floor(pendingAvatar/20)*20+Number(b.dataset.avatarColor);renderAvatarPicker();});
