function parseSentences(text){return text.toLocaleUpperCase('pt-BR').split(/[\n;]+/).map(s=>s.trim().replace(/\s+/g,' ')).filter(Boolean);}
const PLAQUINHAS_SENTENCES=[
['O GATO CORRE RÁPIDO NO JARDIM.','🐱'],['O MENINO BRINCA FELIZ NO PARQUE.','🛝'],['O CARRO ANDA RÁPIDO NA ESTRADA.','🚗'],['A LUA BRILHA ALTO NO CÉU.','🌙'],['O PÁSSARO VOA ALTO NO CÉU.','🐦'],['O CACHORRO LATE FORTE NO PARQUE.','🐶'],['A MENINA FOI PASSEAR NO PARQUE.','🌳'],['A JOANA PLANTOU UMA ÁRVORE NO QUINTAL.','🪴'],['PEDRO FOI AO SHOPPING COMPRAR GRAVATAS.','👔'],['O URSO COME PEIXES E PLANTAS.','🐻'],['A MENINA COMPROU UM PICOLÉ DE AÇAÍ.','🍦'],['EU GOSTO DE COMER BOLO DE CHOCOLATE.','🍰'],['MARIA É UMA MENINA MUITO ESTUDIOSA E DEDICADA.','📚'],['JOÃO COMPROU UM SORVETE DE MORANGO E CHOCOLATE.','🍨'],['MINHA COMIDA PREFERIDA É LASANHA DE CARNE.','🍽️'],['EU FUI À FEIRA COMPRAR LEGUMES E FRUTAS.','🥕'],['COMI UMA TORTA DELICIOSA DE BANANA E CANELA.','🥧'],['A BOLA DO MENINO ERA AZUL E BRANCA.','⚽'],['A MÃE DO MEU AMIGO É PROFESSORA.','📖'],['ANA LEU UM LIVRO NA SALA.','📕'],['EU GOSTO DE TOMAR SUCO DE MANGA.','🥭'],['O PEIXE NADA RÁPIDO NO RIO.','🐟'],['O BALÃO SOBE ALTO NO CÉU.','🎈'],['A VOVÓ GOSTA DE TOMAR CHÁ.','☕']];
function sentenceIdentity(text){return norm(text).replace(/[.!?,;:]+$/g,'').replace(/\s+/g,' ');}
function appendNewSentences(existing,additional){const result=[...existing],known=new Set(existing.map(sentenceIdentity));for(const text of additional){const key=sentenceIdentity(text);if(!known.has(key)){known.add(key);result.push(text);}}return result;}
for(const entry of PLAQUINHAS_SENTENCES)if(!DEFAULT_SENTENCES.some(s=>sentenceIdentity(s[0])===sentenceIdentity(entry[0])))DEFAULT_SENTENCES.push(entry);

const storedSentences=readStore('missao-leitura-sentences-v1',null);
BANKS.frases={name:'Frases em escadinha',description:'A frase cresce uma palavra por linha. A contagem considera apenas as palavras da frase final.',words:Array.isArray(storedSentences)&&storedSentences.length?storedSentences.filter(s=>typeof s==='string'):DEFAULT_SENTENCES.map(s=>s[0])};
if(!readStore('missao-leitura-plaquinhas-20261027',false)){if(Array.isArray(storedSentences)&&storedSentences.length){BANKS.frases.words=appendNewSentences(BANKS.frases.words,PLAQUINHAS_SENTENCES.map(s=>s[0]));saveStore('missao-leitura-sentences-v1',BANKS.frases.words);}saveStore('missao-leitura-plaquinhas-20261027',true);}
const wordCount=text=>String(text).trim().split(/\s+/).filter(Boolean).length;
const readingWeight=(text,mode)=>mode==='frases'?wordCount(text):1;
let previousWordLevel='inicio';
function phraseIllustration(text){return DEFAULT_SENTENCES.find(s=>s[0]===text)?.[1]||'📖';}
function pyramidHTML(text,interactive=false){const words=text.split(/\s+/);return `<div class="pyramid-layout"><div class="pyramid-lines">${words.map((_,i)=>`<div class="stair-line ${i===words.length-1?'last-line':''}">${words.slice(0,i+1).map((w,j)=>interactive&&i===words.length-1?`<button type="button" data-reading-error="${j}" class="stair-word ${game.wordErrors.has(j)?'word-error':''}" aria-label="${escapeHtml(w.replace(/[.!?]/g,''))}: ${game.wordErrors.has(j)?'com dificuldade':'marcar dificuldade'}" aria-pressed="${game.wordErrors.has(j)}"><span>${escapeHtml(w)}</span><i></i></button>`:`<span class="stair-word"><span>${escapeHtml(w)}</span><i></i></span>`).join('')}</div>`).join('')}</div><div class="sentence-picture" aria-hidden="true"><span>${phraseIllustration(text)}</span><small>LEIA E DESCUBRA</small></div></div>`;}
function fitPyramid(target){const lines=target.querySelector('.pyramid-lines');if(!lines)return;lines.style.fontSize='';const last=lines.querySelector('.last-line');if(!last)return;const available=lines.clientWidth;const width=last.scrollWidth;if(width>available&&available>0){const size=parseFloat(getComputedStyle(lines).fontSize);lines.style.fontSize=Math.max(12,size*available/width*.98)+'px';}}
function displayReading(){const phrase=Boolean(game&&game.mode==='frases'&&game.status==='running');$('pyramid').hidden=!phrase;$('word').hidden=phrase;$('sentenceHint').hidden=!phrase;document.querySelector('.word-area').classList.toggle('reading-sentence',phrase);if(phrase){$('pyramid').innerHTML=pyramidHTML(game.words[game.answers.length],true);requestAnimationFrame(()=>fitPyramid($('pyramid')));}}
function configureReadingMode(){if(game&&game.status!=='finished')return;const phrases=$('readingMode').value==='frases';document.body.classList.toggle('sentence-selected',phrases);if(phrases){if($('level').value!=='frases')previousWordLevel=$('level').value;$('level').value='frases';$('target').value=5;}else if($('level').value==='frases'){$('level').value=previousWordLevel;$('target').value=60;}$('targetLabel').textContent=phrases?'Frases na missão':'Palavras na missão';$('targetHelp').textContent=phrases?'Cada frase conta as palavras da última linha. Repetições da escadinha não contam novamente.':'Escolha de 1 a 500. Ative a repetição para reutilizar a lista.';$('correct').innerHTML=phrases?'✓ Registrar frase <kbd>→</kbd>':'✓ Leu <kbd>→</kbd>';$('skip').innerHTML=phrases?'↷ Praticar frase <kbd>←</kbd>':'↷ Precisa praticar <kbd>←</kbd>';if(!game||game.status==='finished')$('word').textContent=phrases?'VAMOS LER FRASES?':'VAMOS LER?';updateSetup();}
$('readingMode').addEventListener('change',configureReadingMode);
$('pyramid').addEventListener('click',event=>{const b=event.target.closest('[data-reading-error]');if(!b||!game||game.status!=='running')return;const index=Number(b.dataset.readingError);if(game.wordErrors.has(index))game.wordErrors.delete(index);else game.wordErrors.add(index);displayReading();});
function renderSentenceBank(){const select=$('sentencePreview');const old=select.value;select.innerHTML=BANKS.frases.words.map((text,i)=>`<option value="${i}">${i+1}. ${escapeHtml(text)}</option>`).join('');if(old!==''&&Number(old)<BANKS.frases.words.length)select.value=old;$('sentenceBankCount').textContent=`${BANKS.frases.words.length} frases disponíveis`;$('sentenceSample').innerHTML=pyramidHTML(BANKS.frases.words[Number(select.value)||0],false);requestAnimationFrame(()=>fitPyramid($('sentenceSample')));}
$('sentencePreview').addEventListener('change',()=>{$('sentenceSample').innerHTML=pyramidHTML(BANKS.frases.words[Number($('sentencePreview').value)||0],false);requestAnimationFrame(()=>fitPyramid($('sentenceSample')));});
$('sentenceEditor').value=BANKS.frases.words.join('\n');
$('saveSentences').addEventListener('click',()=>{if(game&&game.status!=='finished'){toast('Encerre a rodada antes de alterar as frases.');return;}const phrases=parseSentences($('sentenceEditor').value);if(!phrases.length||phrases.length>500||phrases.some(p=>p.length>120||wordCount(p)>12||wordCount(p)<2)){$('sentenceNotice').textContent='Use de 1 a 500 frases, com 2 a 12 palavras e até 120 caracteres por frase.';return;}BANKS.frases.words=phrases;const saved=saveStore('missao-leitura-sentences-v1',phrases);$('sentenceNotice').textContent=saved?'Frases salvas. Sua escadinha está pronta!':'Frases disponíveis nesta sessão; armazenamento indisponível.';renderSentenceBank();updateSetup();});
$('useSentences').addEventListener('click',()=>{if(game&&game.status!=='finished'){toast('Encerre a rodada antes de mudar de modalidade.');return;}$('readingMode').value='frases';configureReadingMode();navigate('jogar');});
window.addEventListener('resize',()=>{fitPyramid($('pyramid'));fitPyramid($('sentenceSample'));});
renderSentenceBank();

function recordMatchesMode(r){const mode=$('dashboardMode').value;return mode==='all'||(r.mode||'palavras')===mode;}
function phrasesDone(r){return r.mode==='frases'?Number(r.cardsAttempted??r.answers.length):0;}
function phrasesGood(r){return r.mode==='frases'?r.answers.filter(a=>a.correct).length:0;}
function phraseRate(r){return r.mode==='frases'&&r.elapsed>0?Number((phrasesGood(r)*60/r.elapsed).toFixed(1)):0;}
function dashboardRate(r){return $('dashboardMode').value==='frases'?phraseRate(r):r.pace;}
function renderDashboard(){renderClassProgress();const mode=$('dashboardMode').value,query=norm($('search').value);const filtered=records.filter(recordMatchesMode).filter(r=>norm(r.name+' '+r.classroom).includes(query));$('totalRounds').textContent=filtered.length;$('totalStudents').textContent=new Set(filtered.map(personKey)).size;$('totalCorrect').textContent=filtered.reduce((n,r)=>n+r.correct,0);$('totalPhrases').textContent=filtered.reduce((n,r)=>n+phrasesDone(r),0);$('totalPhrasesCorrect').textContent=filtered.reduce((n,r)=>n+phrasesGood(r),0);$('wordMetricLabel').textContent=mode==='frases'?'Palavras corretas nas frases':mode==='all'?'Palavras corretas (inclui frases)':'Palavras corretas';$('paceHead').textContent=mode==='frases'?'Frases completas/min':'Palavras corretas/min';$('export').disabled=!records.some(recordMatchesMode);$('emptyState').hidden=filtered.length>0;$('resultsBody').innerHTML=filtered.slice().reverse().map(r=>`<tr><td><span class="record-avatar">${avatarFor(r)}</span><button class="student-link" data-person="${escapeHtml(r.id)}">${escapeHtml(r.name)}</button><small>${escapeHtml(r.classroom||'Sem turma')}</small></td><td>${new Date(r.date).toLocaleDateString('pt-BR')}<small>${new Date(r.date).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></td><td>${escapeHtml(r.listName)}<small>${r.total} palavras${r.mode==='frases'?' · '+r.cardsTotal+' frases':''}</small><small>${r.mode==='frases'?'Modalidade: frases':'Modalidade: palavras'}</small></td><td>${r.correct} de ${r.attempted}<small>${r.accuracy}% de precisão nas palavras</small>${r.mode==='frases'?`<small>${phrasesGood(r)} de ${phrasesDone(r)} frases lidas sem dificuldade</small>`:''}</td><td>${escapeHtml(preciseTime(r.elapsed))}<small>limite: ${timeText(r.limit)}</small></td><td><strong>${numberText(dashboardRate(r))}</strong>${r.mode==='frases'&&mode!=='frases'?`<small>${numberText(phraseRate(r))} frases completas/min</small>`:''}</td><td><button class="details-btn" data-result="${escapeHtml(r.id)}">Ver rodada</button></td></tr>`).join('');if(records.length&&!filtered.length)$('resultsBody').innerHTML='<tr><td colspan="7">Nenhum resultado para o aluno e a modalidade selecionados.</td></tr>';}
function renderClassProgress(){syncRewardCycles();const query=norm($('search').value),week=weekStart(isoDay(new Date())),people=new Map();records.filter(recordMatchesMode).filter(r=>norm(r.name+' '+r.classroom).includes(query)).forEach(r=>{const key=personKey(r);if(!people.has(key))people.set(key,{key,name:r.name,classroom:r.classroom,rounds:[],weeklyCorrect:0,weeklyPhrases:0,weeklyGood:0});const p=people.get(key);p.rounds.push(r);if(weekStart(isoDay(r.date))===week){p.weeklyCorrect+=r.correct;p.weeklyPhrases+=phrasesDone(r);p.weeklyGood+=phrasesGood(r);}});const rows=[...people.values()].map(p=>{const starCorrect=records.filter(r=>personKey(r)===p.key&&weekStart(isoDay(r.date))===week).reduce((n,r)=>n+r.correct,0);const groups=new Map();p.rounds.filter(r=>r.attempted===r.total).forEach(r=>{const k=[r.mode||'palavras',r.level,r.total,r.limit,r.listFingerprint||'original'].join('|');if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r);});const pairs=[...groups.values()].filter(g=>g.length>=2).map(g=>g.sort((a,b)=>a.date.localeCompare(b.date))).sort((a,b)=>b.at(-1).date.localeCompare(a.at(-1).date)),selected=pairs[0],isPhrase=selected?.at(-1).mode==='frases';const firstRate=selected?(isPhrase?phraseRate(selected[0]):selected[0].pace):null,lastRate=selected?(isPhrase?phraseRate(selected.at(-1)):selected.at(-1).pace):null;const cycleReward=rewardStatus(p);return {...p,starCorrect:cycleReward.progress,stars:cycleReward.stars,goalCount:cycleReward.goalCount,prizeCount:cycleReward.prizeCount,gain:selected?Number((lastRate-firstRate).toFixed(1)):null,firstRate,lastRate,gainPercent:selected?(firstRate>0?(lastRate-firstRate)/firstRate*100:lastRate>0?Infinity:0):null,last:selected?.at(-1),unit:isPhrase?'frases completas/min':'palavras corretas/min'};});const sort=$('progressSort').value;rows.sort((a,b)=>sort==='stars'?b.stars-a.stars||b.starCorrect-a.starCorrect:sort==='words'?b.weeklyCorrect-a.weeklyCorrect:(b.gainPercent??-Infinity)-(a.gainPercent??-Infinity)||b.stars-a.stars);$('classProgressBody').innerHTML=rows.length?rows.map(p=>`<tr><td><span class="record-avatar">${avatarFor(p)}</span><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.classroom||'Sem turma')}</small><small>${p.weeklyPhrases} frases avaliadas · ${p.weeklyGood} sem dificuldade nesta semana</small></td><td><span class="progress-stars">★ ${p.stars}/10</span><small>Progresso do ciclo: ${p.starCorrect} acertos · ${p.goalCount} metas · ${p.prizeCount} prêmios</small></td><td>${p.gain===null?'Aguardando duas rodadas comparáveis':`<strong class="${p.gain>0?'gain-positive':''}">${p.gain>0?'+':''}${numberText(p.gain)} ${p.unit}</strong><small>${numberText(p.firstRate)} → ${numberText(p.lastRate)} · ${p.last.accuracy}% de precisão nas palavras</small>`}</td><td>${p.stars===10?'🎁 Prêmio liberado':`Próxima estrela: ${rewardSettings.thresholds[p.stars]} palavras`}</td></tr>`).join(''):'<tr><td colspan="4">Os alunos aparecerão aqui depois da primeira rodada desta modalidade.</td></tr>';}
function renderEvolution(selected){const phrase=$('dashboardMode').value==='frases',all=records.filter(recordMatchesMode).filter(r=>personKey(r)===personKey(selected)).sort((a,b)=>a.date.localeCompare(b.date)),recent=all.slice(-8),rate=r=>phrase?phraseRate(r):r.pace,max=Math.max(1,...recent.map(rate));$('evolution').hidden=false;$('evolution').innerHTML=`<h3>${escapeHtml(selected.name)} · Sua jornada</h3><p>${all.length} rodadas nesta seleção. Barras em ${phrase?'frases completas por minuto':'palavras corretas por minuto'}. Compare a mesma lista, quantidade e limite; considere também a precisão.</p><div class="evolution-bars">${recent.map((r,i)=>`<div class="evolution-item" title="${escapeHtml(r.listName)}: ${r.accuracy}% de precisão; ${phrasesGood(r)} frases completas"><strong>${numberText(rate(r))}</strong><div class="evolution-bar" style="height:${Math.max(2,80*rate(r)/max)}px"></div><span>Rodada ${all.length-recent.length+i+1}</span></div>`).join('')}</div>`;}
$('dashboardMode').addEventListener('change',()=>{$('evolution').hidden=true;renderDashboard();});

const rewardCycles=new RewardCycleBook({state:readStore('missao-leitura-reward-cycles-v2',null),records:()=>records,thresholds:()=>rewardSettings.thresholds,keyFor:personKey,weekFor:date=>weekStart(isoDay(date)),prize:()=>rewardSettings.prize});
rewardCycles.migrate(rewardClaims);
function persistRewardCycles(){if(!rewardCycles.dirty)return true;const saved=saveStore('missao-leitura-reward-cycles-v2',rewardCycles.state);if(saved)rewardCycles.dirty=false;return saved;}
function syncRewardCycles(){rewardCycles.sync();return persistRewardCycles();}
function rewardStatus(person){return rewardCycles.status(typeof person==='string'?person:personKey(person),typeof person==='string'?undefined:person);}
function starsEarned(r){return Number.isFinite(r.rewardStars)?r.rewardStars:legacyStarsEarned(r);}
function starMessage(r){const status=rewardStatus(r),earned=starsEarned(r);return ` ★ +${earned} ${earned===1?'estrela':'estrelas'} nesta rodada. Ciclo atual: ${status.stars}/10 estrelas. Metas concluídas: ${status.goalCount}. Prêmios entregues: ${status.prizeCount}.${status.stars===10&&!status.currentPrize?' Prêmio liberado!':''}`;}
let rewardHistoryKey=null;
function renderStars(){
  syncRewardCycles();
  $('weekLabel').textContent='Ciclo atual: as estrelas acumulam por quantos dias forem necessários e só zeram quando você reinicia.';
  const rows=Object.keys(rewardCycles.state.students).map(key=>rewardCycles.status(key)).sort((a,b)=>b.stars-a.stars||b.progress-a.progress||a.person.name.localeCompare(b.person.name,'pt-BR'));
  $('starRows').innerHTML=rows.length?rows.map((s,index)=>{
    const p=s.person,key=escapeHtml(s.key),reads=records.filter(r=>personKey(r)===s.key),phrases=reads.reduce((n,r)=>n+phrasesDone(r),0),good=reads.reduce((n,r)=>n+phrasesGood(r),0),next=rewardSettings.thresholds[s.stars];
    const pendingOther=s.pending.filter(g=>g.cycleId!==s.cycle.id).length;
    return `<article class="star-row cycle-row"><span class="rank">${index+1}</span><span class="mural-avatar">${avatarFor(p)}</span><div class="star-person"><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.classroom||'Sem turma')} · ${s.total} palavras corretas no histórico · ${good} de ${phrases} frases sem dificuldade</p><div class="star-icons" aria-label="${s.stars} de 10 estrelas">${Array.from({length:10},(_,i)=>`<span class="${i<s.stars?'earned':''}">★</span>`).join('')}<strong>${s.stars}/10</strong></div><div class="achievement-counts"><span>🏆 ${s.goalCount} ${s.goalCount===1?'meta de 10 estrelas':'metas de 10 estrelas'}</span><span>🎁 ${s.prizeCount} ${s.prizeCount===1?'prêmio entregue':'prêmios entregues'}</span></div><p>${s.stars===10?(s.currentPrize?'Prêmio deste ciclo já registrado. Você pode recomeçar.':'🎁 Prêmio liberado: '+escapeHtml(rewardSettings.prize)):`${Math.max(0,next-s.progress)===1?'Falta 1 palavra correta':'Faltam '+Math.max(0,next-s.progress)+' palavras corretas'} para a próxima estrela.`}</p><p class="cycle-detail">Ciclo ${s.cycle.number||1} · Progresso para esta meta: ${s.progress}/${rewardCycles.cap()} acertos${pendingOther?` · ${pendingOther} ${pendingOther===1?'prêmio anterior pendente':'prêmios anteriores pendentes'}`:''}</p><div class="cycle-actions">${s.stars===10&&!s.currentPrize?`<button class="primary" data-reward-action="prize-reset" data-reward-person="${key}">🎁 Premiar e recomeçar</button><button class="secondary" data-reward-action="prize" data-reward-person="${key}">Só registrar prêmio</button>`:''}<button class="reward-adjust" data-reward-action="remove" data-reward-person="${key}" ${s.stars===0?'disabled':''}>− 1 estrela</button><button class="reward-adjust" data-reward-action="reset" data-reward-person="${key}" ${s.progress===0?'disabled':''}>↻ Zerar estrelas</button><button class="reward-adjust" data-reward-action="history" data-reward-person="${key}">▤ Histórico</button>${s.canUndo?`<button class="reward-undo" data-reward-action="undo" data-reward-person="${key}">↶ Desfazer último ajuste</button>`:''}</div></div></article>`;
  }).join(''):'<div class="star-empty">★<h3>Vamos conquistar a primeira estrela?</h3><p>Conclua uma rodada para começar. As conquistas continuarão registradas quando você reiniciar as estrelas.</p></div>';
  renderMilestones();persistRewardCycles();
}
function rewardEntryLabel(entry){
  if(entry.kind==='goal')return '🏆 Completou 10 estrelas';
  if(entry.kind==='prize')return '🎁 Prêmio entregue: '+entry.label;
  return {remove:'− Retirou uma estrela',reset:'↻ Zerou estrelas e iniciou outro ciclo','prize-reset':'↻ Recomeçou após entregar o prêmio'}[entry.type]||'Ajuste de estrelas';
}
function historyInPeriod(entry,filter){const day=isoDay(entry.at),today=isoDay(new Date());return filter==='all'||filter==='month'&&day.slice(0,7)===today.slice(0,7)||filter==='week'&&weekStart(day)===weekStart(today);}
function renderRewardHistory(){
  if(!rewardHistoryKey)return;const status=rewardCycles.status(rewardHistoryKey),person=status.person,filter=$('rewardHistoryFilter').value,entries=rewardCycles.history(rewardHistoryKey).filter(e=>historyInPeriod(e,filter));
  $('rewardHistoryTitle').textContent=person.name+' · Conquistas';
  $('rewardHistorySummary').innerHTML=`<div><strong>${status.goalCount}</strong><span>metas de 10 estrelas</span></div><div><strong>${status.prizeCount}</strong><span>prêmios entregues</span></div><div><strong>${status.stars}/10</strong><span>estrelas no ciclo atual</span></div>`;
  const periodGoals=entries.filter(e=>e.kind==='goal').length,periodPrizes=entries.filter(e=>e.kind==='prize'&&!e.voidedAt).length;$('rewardHistoryPeriodSummary').textContent=`Neste período: ${periodGoals} ${periodGoals===1?'meta':'metas'} e ${periodPrizes} ${periodPrizes===1?'prêmio entregue':'prêmios entregues'}.`;
  $('rewardHistoryRows').innerHTML=entries.length?entries.map(e=>{
    const undone=e.undoneAt||e.voidedAt,pending=e.kind==='goal'&&!rewardCycles.activePrizes(person).some(p=>p.goalId===e.id);
    return `<div class="reward-history-entry ${undone?'undone':''}"><div><strong>${escapeHtml(rewardEntryLabel(e))}</strong><small>${new Date(e.at).toLocaleString('pt-BR')}${e.source==='legacy'?' · registro anterior preservado':''}</small>${e.kind==='adjustment'?`<small>${e.beforeStars}/10 → ${e.afterStars}/10 estrelas</small>`:''}${undone?`<small>Desfeito em ${new Date(undone).toLocaleString('pt-BR')}</small>`:''}</div>${pending?`<button class="small-btn" data-reward-action="history-prize" data-reward-person="${escapeHtml(rewardHistoryKey)}" data-reward-goal="${escapeHtml(e.id)}">Registrar entrega</button>`:''}</div>`;
  }).join(''):'<p class="field-help">Nenhum registro neste período.</p>';
  persistRewardCycles();
}
function openRewardHistory(key){rewardHistoryKey=key;$('rewardHistoryFilter').value='all';renderRewardHistory();if(!$('rewardHistoryDialog').open)$('rewardHistoryDialog').showModal();}
function handleRewardAction(event){
  const b=event.target.closest('[data-reward-action]');if(!b)return;const key=b.dataset.rewardPerson,action=b.dataset.rewardAction;
  if(action==='history'){openRewardHistory(key);return;}
  const status=rewardCycles.status(key);let result;
  if(action==='remove')result=rewardCycles.removeStar(key);
  else if(action==='reset')result=rewardCycles.reset(key);
  else if(action==='undo')result=rewardCycles.undo(key);
  else if(action==='history-prize')result=rewardCycles.award(key,b.dataset.rewardGoal,false);
  else if(action==='prize'||action==='prize-reset')result=rewardCycles.award(key,status.goal?.id,action==='prize-reset');
  if(!result)return;if(!result.ok){toast(result.message);return;}
  const saved=persistRewardCycles();renderStars();if($('rewardHistoryDialog').open)renderRewardHistory();
  const messages={remove:'Uma estrela retirada. O histórico de leitura foi preservado.',reset:'Estrelas zeradas. Metas e prêmios anteriores continuam no histórico.',undo:'Último ajuste desfeito.','history-prize':'Entrega do prêmio registrada.',prize:'Entrega do prêmio registrada.','prize-reset':'Prêmio registrado e novo ciclo iniciado!'};
  toast(saved?messages[action]:'Atualizado nesta sessão. Não foi possível salvar no navegador; exporte o histórico antes de fechar.');
}
$('starRows').addEventListener('click',handleRewardAction);$('rewardHistoryRows').addEventListener('click',handleRewardAction);
$('rewardHistoryFilter').addEventListener('change',renderRewardHistory);$('closeRewardHistory').addEventListener('click',()=>$('rewardHistoryDialog').close());
function exportRewardHistory(singleKey){
  syncRewardCycles();const keys=singleKey?[singleKey]:Object.keys(rewardCycles.state.students),rows=[['Aluno','Turma','Metas de 10 estrelas concluídas','Prêmios entregues','Tipo','Data e hora','Registro','Desfeito em']];
  for(const key of keys){const status=rewardCycles.status(key);for(const e of rewardCycles.history(key))rows.push([status.person.name,status.person.classroom,status.goalCount,status.prizeCount,e.kind==='goal'?'Meta':e.kind==='prize'?'Prêmio':'Ajuste',new Date(e.at).toLocaleString('pt-BR'),rewardEntryLabel(e),e.undoneAt||e.voidedAt?new Date(e.undoneAt||e.voidedAt).toLocaleString('pt-BR'):'']);}
  const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='missao-leitura-conquistas-e-premios.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
$('exportRewards').addEventListener('click',()=>exportRewardHistory());$('exportRewardHistory').addEventListener('click',()=>exportRewardHistory(rewardHistoryKey));
syncRewardCycles();

$('previewLevel').value='mistas';renderStudents();renderBank();renderStars();updateSetup();navigate(location.hash.slice(1)||'inicio');if(!storageOK)toast('Armazenamento indisponível. Exporte os resultados antes de fechar.');

function colorWord(){const colors=['#24634e','#a72769','#3555aa','#946515','#7043a4','#ae4937'];$('word').style.setProperty('--word-color',$('colorWords').checked&&game?colors[game.answers.length%colors.length]:'#1b1b3a');}

$('useBank').addEventListener('click',()=>{if(game&&game.status!=='finished'){toast('Encerre a rodada antes de escolher outra lista.');return;}$('readingMode').value='palavras';configureReadingMode();$('level').value=$('previewLevel').value;const count=BANKS[$('level').value].words.length;$('target').value=Math.min(60,count||1);updateSetup();navigate('jogar');});

function resetFuseVisual(){const fuse=$('fuse');const tip=fuse.getPointAtLength(fuse.getTotalLength());$('spark').setAttribute('transform',`translate(${tip.x} ${tip.y})`);$('fuseMask').style.strokeDasharray='100 100';}
